// Cache the identical ordered transport graph only within one synchronous arrival.
// Matches and shortest-path distances remain evaluated per passenger query.

function studyAdjacency(u,context){if(context.adj.has(u))return context.adj.get(u);let edges=[];
 for(let l of S.lines){if(l.retiring||l.type==='air'&&weatherFactor(S.cities[u],'air')===0)continue;for(let idx=0;idx<l.stops.length;idx++){if(l.stops[idx]!==u)continue;let groups=new Map();for(let v of S.vehicles.filter(v=>v.line===l.id&&!v.recall)){if(!serves(v,l,idx)||!sameComponent(v,l,idx))continue;let sig=JSON.stringify([v.service||{},fullLoop130(v,l)?v.dir:0]);if(!groups.has(sig))groups.set(sig,[]);groups.get(sig).push(v);}for(let vs of groups.values()){let v=vs[0],{lo,hi}=serviceRange(v,l),round=0;for(let j=lo+1;j<=hi;j++){let t=serviceTravelTime(v,l,j-1,1);round+=Number.isFinite(t)?t+1:25;}let wait=Math.min(25,round/Math.max(1,vs.length));for(let dir of fullLoop130(v,l)?[v.dir]:[-1,1]){let travel=0;for(let j=idx+dir;j>=lo&&j<=hi;j+=dir){let a=S.cities[l.stops[j-dir]],b=S.cities[l.stops[j]];if(!canEnter(a,b,l.type))break;let time=serviceTravelTime(v,l,j-dir,dir);if(!Number.isFinite(time))break;travel+=time;if(serves(v,l,j)){edges.push({to:b.id,travel,wait,transfer:TYPES[l.type].transfer*(S.cities[u].hub?.7:1),first:{line:l.id,next:l.stops[idx+dir],vehicleIds:vs.map(x=>x.id)}});break;}}}}}
 } context.adj.set(u,edges);return edges;}
function studyPlanCore(start,p,context){let n=S.cities.length,dist=Array(n).fill(Infinity),first=Array(n).fill(null),done=new Set();dist[start]=0;for(let turn=0;turn<n;turn++){let u=-1;for(let i=0;i<n;i++)if(!done.has(i)&&(u<0||dist[i]<dist[u]))u=i;if(u<0||!Number.isFinite(dist[u]))break;done.add(u);if(u!==start&&matchesDestination(S.cities[u],p))return {...first[u],target:u,time:dist[u]};for(let e of studyAdjacency(u,context)){let nd=dist[u]+e.travel+e.wait+e.transfer;if(nd<dist[e.to]){dist[e.to]=nd;first[e.to]=first[u]||e.first;}}}return null;}
plan=function(start,p){let exact=p.schoolId!==undefined||!!p.eventId||!!p.cardId||!!p.fixedDestination,key=JSON.stringify([start,p.origin,exact,exact?p.dest:null,p.color,p.shape,p.destRegion??null]);if(routingBatch?.routes.has(key))return routingBatch.routes.get(key);let context=routingBatch?(routingBatch.studyGraph??={adj:new Map()}):{adj:new Map()},r=studyPlanCore(start,p,context);if(routingBatch)routingBatch.routes.set(key,r);return r;};
